const revenueByMethod = `-- name: RevenueByMethod :many

SELECT p.method, count(*)::bigint AS payments, COALESCE(sum(p.gross_amount), 0)::bigint AS gross,
    COALESCE((SELECT sum(r.amount) FROM refunds r JOIN payments px ON px.id = r.payment_id WHERE px.method = p.method AND r.status = 'COMPLETED'
        AND r.completed_at >= $1::timestamptz AND r.completed_at < $2::timestamptz), 0)::bigint AS refunded
FROM payments p
WHERE p.status = 'SUCCEEDED' AND p.paid_at >= $1::timestamptz AND p.paid_at < $2::timestamptz
GROUP BY p.method ORDER BY p.method
`

type RevenueByMethodParams struct {
	FromTime time.Time `json:"from_time"`
	ToTime   time.Time `json:"to_time"`
}

type RevenueByMethodRow struct {
	Method   string `json:"method"`
	Payments int64  `json:"payments"`
	Gross    int64  `json:"gross"`
	Refunded int64  `json:"refunded"`
}

// Reports and overview
func (q *Queries) RevenueByMethod(ctx context.Context, arg RevenueByMethodParams) ([]RevenueByMethodRow, error) {
	rows, err := q.db.Query(ctx, revenueByMethod, arg.FromTime, arg.ToTime)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []RevenueByMethodRow{}
	for rows.Next() {
		var i RevenueByMethodRow
		if err := rows.Scan(
			&i.Method,
			&i.Payments,
			&i.Gross,
			&i.Refunded,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const reviewStats = `-- name: ReviewStats :one
SELECT count(*)::bigint AS total, COALESCE(avg(rating_overall), 0)::float8 AS overall, COALESCE(avg(rating_boat), 0)::float8 AS boat,
    COALESCE(avg(rating_service), 0)::float8 AS service, COALESCE(avg(rating_crew), 0)::float8 AS crew
FROM reviews WHERE status = 'PUBLISHED' AND boat_id = $1
`

type ReviewStatsRow struct {
	Total   int64   `json:"total"`
	Overall float64 `json:"overall"`
	Boat    float64 `json:"boat"`
	Service float64 `json:"service"`
	Crew    float64 `json:"crew"`
}

func (q *Queries) ReviewStats(ctx context.Context, boatID uuid.UUID) (ReviewStatsRow, error) {
	row := q.db.QueryRow(ctx, reviewStats, boatID)
	var i ReviewStatsRow
	err := row.Scan(
		&i.Total,
		&i.Overall,
		&i.Boat,
		&i.Service,
		&i.Crew,
	)
	return i, err
}

